// --- Brick collision (resolution of issue #1) ------------------------------

// Penetration depths of the ball's box on each side of the brick.
function facePenetration(ball, brick) {
  return {
    left: ball.x + ball.r - brick.x,
    right: brick.x + brick.w - (ball.x - ball.r),
    top: ball.y + ball.r - brick.y,
    bottom: brick.y + brick.h - (ball.y - ball.r),
  };
}

