// face(s) that were hit (the axis with the SMALLER penetration; both axes on
// a diagonal/corner hit) and pushes the ball back outside the brick so it
// cannot re-overlap on the next frame (sticky bounce).
export function bounceOffBrick(ball, brick) {
  const pen = facePenetration(ball, brick);
  const min = Math.min(pen.left, pen.right, pen.top, pen.bottom);

  const onLeft = Math.abs(pen.left - min) < 1e-9;
  const onRight = Math.abs(pen.right - min) < 1e-9;
  const onTop = Math.abs(pen.top - min) < 1e-9;
  const onBottom = Math.abs(pen.bottom - min) < 1e-9;

  const flipX = onLeft || onRight;
  const flipY = onTop || onBottom;

  if (flipX) {
    ball.vx = onLeft ? Math.abs(ball.vx) : -Math.abs(ball.vx);
    ball.x = onLeft ? brick.x - ball.r : brick.x + brick.w + ball.r;
  }
  if (flipY) {
    ball.vy = onTop ? Math.abs(ball.vy) : -Math.abs(ball.vy);
    ball.y = onTop ? brick.y - ball.r : brick.y + brick.h + ball.r;
  }
}
