```js
// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle AND the bricks (issue #1). Brick destruction, scoring
// and the per-face bounce happen in `resolveBricks`; the ball is swept along
// its travelled segment so a fast ball cannot tunnel through a brick.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  const prevX = ball.x;
  const prevY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    // The rebound angle depends on where the paddle was hit.
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0; // touching the paddle resets the combo
  }

  // Bricks (issue #1): sweep + per-face bounce + scoring.
  resolveBricks(state, prevX, prevY);

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}
```

New brick collision section (replace the comment about collision primitive and add the resolution functions after `collides`):

```js
// --- Collision (tested primitives) -----------------------------------------

// True if a circle of radius `r` centred at (x, y) overlaps the brick box.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit (see bounceOffBrick below for the face resolution).
function circleBoxHit(x, y, r, brick) {
  return (
    x + r > brick.x &&
    x - r < brick.x + brick.w &&
    y + r > brick.y &&
    y - r < brick.y + brick.h
  );
}

// True if the ball (circle approximated by its box) overlaps the brick.
export function collides(ball, brick) {
  return circleBoxHit(ball.x, ball.y, ball.r, brick);
}

// --- Brick bounce (issue #1) -----------------------------------------------

// Bounces the ball off the brick it overlaps and pushes it back outside.
// The axis with the SMALLER penetration is the face that was hit: flip `vy`
// on a top/bottom hit, `vx` on a side hit and leave the other component
// exactly as it was. Equal penetrations (a diagonal hit into a corner) flip
// both components. Repositioning the ball outside the brick prevents a
// "sticky" bounce where it re-overlaps on the next frame and flips forever.
export function bounceOffBrick(ball, brick) {
  const left = ball.x + ball.r - brick.x;
  const right = brick.x + brick.w - (ball.x - ball.r);
  const top = ball.y + ball.r - brick.y;
  const bottom = brick.y + brick.h - (ball.y - ball.r);
  const min = Math.min(left, right, top, bottom);

  const EPS = 1e-9;
  const hitLeft = Math.abs(left - min) < EPS;
  const hitRight = Math.abs(right - min) < EPS;
  const hitTop = Math.abs(top - min) < EPS;
  const hitBottom = Math.abs(bottom - min) < EPS;

  if (hitLeft || hitRight) {
    ball.vx = hitLeft ? Math.abs(ball.vx) : -Math.abs(ball.vx);
    ball.x = hitLeft ? brick.x - ball.r : brick.x + brick.w + ball.r;
  }
  if (hitTop || hitBottom) {
    ball.vy = hitTop ? Math.abs(ball.vy) : -Math.abs(ball.vy);
    ball.y = hitTop ? brick.y - ball.r : brick.y + brick.h + ball.r;
  }
}

// Sweeps the ball along the segment it travelled this step (from (prevX,
// prevY) to its current position) and resolves every brick it crossed.
// Sweeping prevents tunnelling: at level 6 the ball moves 35.5 px/step, more
// than the 34 px it takes to cross a brick, so checking only the final
// position would let it jump straight through. When several bricks overlap at
// the same point (the 8 px grid gap is smaller than the 14 px ball, so seams
// touch two bricks in the same pass) the bounce is applied EXACTLY once and
// every touched brick is destroyed, so `vy = -vy` cannot be applied twice and
// cancel out.
function resolveBricks(state, prevX, prevY) {
  const { ball } = state;
  const travelled = Math.hypot(ball.x - prevX, ball.y - prevY);
  const samples = Math.max(1, Math.ceil(travelled / 10));

  for (let i = 1; i <= samples; i++) {
    const t = i / samples;
    const sx = prevX + (ball.x - prevX) * t;
    const sy = prevY + (ball.y - prevY) * t;

    // Every brick touched at this point along the path.
    const touched = state.bricks.filter((b) => b.alive && circleBoxHit(sx, sy, ball.r, b));
    if (touched.length === 0) continue;

    // Snap the ball to the impact point, then bounce it off the most direct
    // hit (the brick it penetrated the least).
    ball.x = sx;
    ball.y = sy;
    let deepest = touched[0];
    let deepestPen = Infinity;
    for (const brick of touched) {
      const pen = Math.min(
        ball.x + ball.r - brick.x,
        brick.x + brick.w - (ball.x - ball.r),
        ball.y + ball.r - brick.y,
        brick.y + brick.h - (ball.y - ball.r),
      );
      if (pen < deepestPen) {
        deepestPen = pen;
        deepest = brick;
      }
    }
    bounceOffBrick(ball, deepest);

    // Destroy every brick the ball touched (combo counts each one).
    for (const brick of touched) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
    }
    break; // one bounce per step is enough
  }
}
```

