test('bounceOffBrick: top hit flips vy, keeps vx and pushes the ball out', () => {
  const ball = { x: 100, y: 105, r: 7, vx: 30, vy: 120 };
  const brick = { x: 90, y: 100, w: 40, h: 20 };
  bounceOffBrick(ball, brick);
  assert.equal(ball.vy, -120, 'vertical velocity flips away from the top face');
  assert.equal(ball.vx, 30, 'horizontal velocity is untouched');
  assert.equal(ball.y, 93, 'ball is pushed back above the brick');
  assert.equal(collides(ball, brick), false, 'no overlap left (no sticky bounce)');
});

test('bounceOffBrick: side hit flips vx, keeps vy and pushes the ball out', () => {
  const ball = { x: 95, y: 105, r: 7, vx: -150, vy: 40 };
  const brick = { x: 100, y: 100, w: 40, h: 20 };
  bounceOffBrick(ball, brick);
  assert.equal(ball.vx, 150, 'horizontal velocity flips away from the side face');
  assert.equal(ball.vy, 40, 'vertical velocity is untouched');
  assert.equal(ball.x, 93, 'ball is pushed back to the left of the brick');
  assert.equal(collides(ball, brick), false);
});

test('bounceOffBrick: corner hit (equal penetration) flips both components', () => {
  const ball = { x: 103, y: 103, r: 7, vx: -90, vy: -120 };
  const brick = { x: 100, y: 100, w: 40, h: 20 };
  bounceOffBrick(ball, brick);
  assert.equal(ball.vx, 90);
  assert.equal(ball.vy, 120);
  assert.equal(collides(ball, brick), false);
});

test('step: two bricks at a seam bounce the ball exactly once', () => {
  const state = createState(1);
  // Row 0 spans x=4..76 and x=84..156 (8 px gap). The ball overlaps both top
  // faces at once; a double `vy = -vy` would cancel out and go straight through.
  state.ball = { x: 80, y: 55, r: 7, vx: 0, vy: 150 };
  step(state, 0);
  assert.ok(state.ball.vy < 0, 'vy must be flipped exactly once');
  const dead = state.bricks.filter((b) => !b.alive).length;
  assert.equal(dead, 2, 'both touched bricks are destroyed');
});

test('step: fast ball cannot tunnel through a brick (sweep)', () => {
  const state = createState(1);
  // From y=40 to y=90 in one step the ball clears the brick (bottom edge at 68)
  // entirely; only the sweep between the two positions catches it mid-flight.
  const brick = state.bricks.find((b) => b.row === 0 && b.x === 4);
  state.ball = { x: 40, y: 40, r: 7, vx: 0, vy: 1000 };
  step(state, 0.05);
  assert.ok(state.ball.vy < 0, 'the sweep must bounce the ball off the brick');
  assert.equal(brick.alive, false);
});

