// Sweeps the ball along the segment it travelled this step (from (prevX,
// prevY) to its current position) and resolves every brick it crossed.
//
// Sweeping prevents tunnelling: at level 6 the ball moves 35.5 px/step, more
// than the 34 px it takes to cross a brick, so checking only the final
// position would let it jump straight through. The step is sampled every
// SAMPLE_STEP px — fine enough to catch first contact while the penetration
// along the approach axis is still the smallest. That matters at seams: a
// ball centred on the 8 px gap is 3 px into each neighbour, so unless a
// downward shot is caught while its top/bottom penetration is still under
// that 3 px, it would read as a side hit and slip through the seam.
//
// When several bricks overlap at the same point, the bounce is applied
// EXACTLY once, off the brick the ball penetrated the least — `vy = -vy`
// applied twice cancels out and the ball goes through — and every touched
// brick is destroyed.
const SAMPLE_STEP = 2;

function resolveBricks(state, prevX, prevY) {
  const { ball } = state;
  const travelled = Math.hypot(ball.x - prevX, ball.y - prevY);
  const samples = Math.max(1, Math.ceil(travelled / SAMPLE_STEP));

